import hashlib


class ArtifactStore:
    def __init__(self):
        self.artifacts = {}

    def upload(self, name, data):
        checksum = hashlib.sha256(data).hexdigest()[:8]
        self.artifacts[name] = {"data": data, "checksum": checksum}
        return checksum

    def download(self, name):
        return self.artifacts[name]["data"]


store = ArtifactStore()
binary = b"compiled-app-v1"

checksum = store.upload("app-binary", binary)
print("uploaded app-binary, checksum", checksum)

downloaded = store.download("app-binary")
print("deploy job received:", downloaded.decode())
